params.ts_type:
({
  id: string
  title: string | null
  pinned: boolean
  /** 用户当前停留的消息，线性化消息树的唯一依据 */
  current_message_id: number
  inserted_at: string
  updated_at: string
  /** 消息树，分支靠 parent_id */
  messages: ({
  /** 会话内自增 */
  id: number
  /** null 表示该会话的第一条 */
  parent_id: number | null
  role: ('USER' | 'ASSISTANT')
  status: (| 'WIP'
  | 'FINISHED'
  | 'CONTENT_FILTER'
  | 'FAILED'
  | 'INCOMPLETE'
  | 'CONTEXT_LENGTH_EXCEEDED'
  | 'TIMEOUT')
  thinking_enabled: boolean
  search_enabled: boolean
  /** 沿分支累计的上下文 token */
  accumulated_token_usage: number
  inserted_at: string
  /** 按发生顺序排列 */
  fragments: (| { type: 'REQUEST'; content: string }
  | { type: 'RESPONSE'; content: string }
  | ({
  type: 'THINK'
  content: string
  /** 思考耗时（秒） */
  elapsed_secs: number | null
})
  | { type: 'TEMPLATE_RESPONSE'; content: string }
  | { type: 'TIP'; content: string; style: TipStyle }
  | { type: 'CONTENT_RISK'; content: string; style: TipStyle }
  | {
  type: 'PARTIAL_FILE_READ'
  /** 截断后占原文的百分比，0–100 */
  ratio: number
}
  | {
  type: 'TOOL_SEARCH'
  queries: string[]
  results: SearchResult[]
  /** 可选的搜索状态；FINISHED 允许空结果 */
  status?: SearchStatus
  /** 可选的模型推理轮次编号 */
  stage_id?: number
  /** 部分产物携带的分组标识，原样保留 */
  group_id?: number
}
  | ({
  type: 'TOOL_OPEN'
  status: ToolOpenStatus
  url: string | null
  title: string | null
  snippet?: string | null
  site_name?: string | null
  published_at: Iso8601Utc | null
  stage_id?: number
  group_id?: number
})
  | {
  type: 'TOOL_FIND'
  status: ToolFindStatus
  pattern?: string
  stage_id?: number
  group_id?: number
}
  | { type: 'READ_LINK'; results: ReadLinkResult[] }
  | { type: 'FILE'; files: FileEntry[] }
  | {
  type: 'TOOL_IMAGE_SEARCH'
  status: ImageSearchStatus
  image_indexes?: number[]
  results: ImageSearchResult[]
  stage_id?: number
  group_id?: number
})[]
})[]
})

exports.returns:
{
  session: ({
  id: string
  title: string
  createdAt: number
  updatedAt: number
  /** 包含所有分支的消息，按创建顺序存储。 */
  messages: (MessageBranch & {
  id: string
  role: 'user'
  content: string
  files: FileAttachment[]
  createdAt: number
} | (MessageBranch & {
  id: string
  role: 'assistant'
  createdAt: number
  /** 未记录模型时为 null，续写使用当前默认模型。 */
  model: ChatModel | null
  /** 请求时是否开启深度思考 */
  thinking?: boolean
  /** 请求时是否声明 deepseek_web_search；关闭时仍声明 deepseek_read_url */
  search?: boolean
  /** 本轮请求的系统信息快照；各回答版本独立保存，续写沿用。历史消息中缺省的快照保持为空。 */
  latestReminder?: string
  /** 是否允许作为续写前缀；仍需满足回复状态与内容限制。 */
  prefix: boolean
  status: ReplyStatus
  /** 可识别的内容块按接收顺序排列；续写产生的块追加在已有块之后 */
  blocks: ReplyBlock[]
  stopReason?: StopReason
  stopDetails?: StopDetails
  /** 最近一次请求的用量，续写后更新 */
  usage?: MessageUsage
  error?: {
    /** upload：发送前补传附件失败，请求没有发出 */
    kind: ApiErrorKind | 'upload'
    message: string
    status?: number
    localMessage?: TranslationMessage
    /** 仅 upload：重新上传是否可能成功（网络、限流、服务端繁忙）；过大、格式不支持为 false */
    retryable?: boolean
  }
}))[]
  /** undefined 表示线性消息列表；null 表示空会话。 */
  rootMessageId?: string | null
  /** 上一轮的 token 用量（含缓存命中情况） */
  contextUsage?: {
  inputTokens: number
  outputTokens: number
  cacheReadTokens: number
  cacheWriteTokens: number
  updatedAt: number
}
  /** 开头存档，编译一次后冻结，保证长对话仍记得最初内容 */
  anchor?: {
  text: string
  upTo: string
  createdAt: number
}
  /** 事实账本：只追加，覆盖中段对话，裁剪也不会丢 */
  memory?: {
  index: number
  fromRound: number
  toRound: number
  text: string
  createdAt: number
}[]
})
  /** 本会话目录下应存在的图片：ZIP 条目名 → 文件 ID */
  images: Map<string, string>
}
